namespace PersonalAIAssistant.Memory.Core.Interfaces.Security
{
    /// <summary>
    /// Envelope data key generated by Hardware Security Module (HSM).
    /// </summary>
    public sealed record HsmEnvelopeKey(
        byte[] PlaintextKey,
        byte[] WrappedKey,
        string KeyIdentifier,
        string KeyVersion);

    /// <summary>
    /// Service for communicating with FIPS 140-2 Level 3 Hardware Security Modules
    /// (Azure Key Vault Managed HSM, AWS KMS CloudHSM, or FIPS-compliant local provider).
    /// </summary>
    public interface IHsmKeyVaultService
    {
        /// <summary>
        /// Retrieves a secret (e.g. JWT signing secret) stored in the HSM / Key Vault.
        /// </summary>
        Task<string> GetSecretAsync(string secretName, CancellationToken ct = default);

        /// <summary>
        /// Wraps (encrypts) an ephemeral Data Encryption Key (DEK) inside the HSM boundary using the Master KEK.
        /// </summary>
        Task<byte[]> WrapKeyAsync(string keyName, byte[] plaintextDek, CancellationToken ct = default);

        /// <summary>
        /// Unwraps (decrypts) an ephemeral Data Encryption Key (DEK) inside the HSM boundary using the Master KEK.
        /// </summary>
        Task<byte[]> UnwrapKeyAsync(string keyName, byte[] wrappedDek, CancellationToken ct = default);

        /// <summary>
        /// Generates an ephemeral 256-bit Data Encryption Key inside the HSM boundary.
        /// </summary>
        Task<HsmEnvelopeKey> GenerateDataKeyAsync(string keyName, CancellationToken ct = default);

        /// <summary>
        /// Instantly revokes/shreds a tenant's Master KEK, making all associated encrypted payloads permanently unrecoverable.
        /// </summary>
        Task<bool> RevokeKeyAsync(string keyName, CancellationToken ct = default);

        /// <summary>
        /// Active HSM Provider name (e.g. "AzureKeyVaultManagedHsm", "AwsKmsHsm", "SimulatedHsm").
        /// </summary>
        string ProviderName { get; }

        /// <summary>
        /// Verified hardware compliance level (e.g. "FIPS 140-2 Level 3").
        /// </summary>
        string FipsComplianceLevel { get; }

        /// <summary>
        /// True if backed by dedicated physical HSM hardware.
        /// </summary>
        bool IsHsmBacked { get; }
    }
}
